# 组织模板里原本接近 1:1 的岗位会让大量没有明确女性定位的普通
# 职位偏向女性。统一提高这些岗位的男性权重；女性明显占优、纯女性
# 以及本来就明显偏男性的岗位保持模板原值，不抹掉职业性别特征。
BALANCED_ROLE_SEX_MIN_MALE_SHARE = 0.35
BALANCED_ROLE_SEX_MAX_MALE_SHARE = 0.65
BALANCED_ROLE_MALE_WEIGHT_MULTIPLIER = 4.0


def _increase_balanced_role_male_weights() -> int:
    adjusted = 0
    for templates in ORGANIZATION_TEMPLATES.values():
        for template in templates.values():
            for role in template.get("roles", {}).values():
                weights = role.get("sex")
                if not isinstance(weights, dict):
                    continue
                male = weights.get("male")
                female = weights.get("female")
                if (
                    isinstance(male, bool)
                    or isinstance(female, bool)
                    or not isinstance(male, (int, float))
                    or not isinstance(female, (int, float))
                    or male <= 0
                    or female <= 0
                ):
                    continue
                male_share = male / (male + female)
                if not (
                    BALANCED_ROLE_SEX_MIN_MALE_SHARE
                    <= male_share
                    <= BALANCED_ROLE_SEX_MAX_MALE_SHARE
                ):
                    continue
                weights["male"] = round(
                    male * BALANCED_ROLE_MALE_WEIGHT_MULTIPLIER,
                    6,
                )
                adjusted += 1
    return adjusted


BALANCED_ROLE_SEX_ADJUSTED_COUNT = _increase_balanced_role_male_weights()

