def _extend_sex_service_visit_occupation_profiles() -> int:
    before = len(SEX_SERVICE_VISIT_OCCUPATION_TIME_PROFILE)
    for category, groups in OCCUPATION_TEMPLATES.items():
        if category == "FREELANCER":
            for occupation in groups:
                if occupation in {"无业游民", "闲散人员"}:
                    profile = "unemployed"
                elif any(marker in occupation for marker in ("司机", "骑手", "跑腿")):
                    profile = "mobile_shift"
                else:
                    profile = "flexible"
                SEX_SERVICE_VISIT_OCCUPATION_TIME_PROFILE.setdefault(
                    occupation,
                    profile,
                )
            continue

        if category == "SEX_SERVICE_OCCUPATIONS":
            for occupation in groups:
                SEX_SERVICE_VISIT_OCCUPATION_TIME_PROFILE.setdefault(
                    occupation,
                    "night_shift",
                )
            continue

        default_profile = {
            "DAILY_OCCUPATIONS": "day_shift",
            "PROFESSIONAL_OCCUPATIONS": "day_shift",
            "GREY_OCCUPATIONS": "underground",
            "ILLEGAL_OCCUPATIONS": "underground",
        }[category]
        configured_groups = _SEX_SERVICE_VISIT_GROUP_PROFILES.get(category, {})
        for group_name, occupations in groups.items():
            profile = configured_groups.get(group_name, default_profile)
            for occupation in occupations:
                SEX_SERVICE_VISIT_OCCUPATION_TIME_PROFILE.setdefault(
                    occupation,
                    profile,
                )
    return len(SEX_SERVICE_VISIT_OCCUPATION_TIME_PROFILE) - before


SEX_SERVICE_VISIT_OCCUPATION_PROFILE_ADDED_COUNT = (
    _extend_sex_service_visit_occupation_profiles()
)

